(() => {
  'use strict';
  const canvas = document.getElementById('scene');
  const ctx = canvas.getContext('2d');
  const W = canvas.width, H = canvas.height;
  const ui = Object.fromEntries(['tree','propertyContent','statusText','coords','objectCount','toast','outputMessage','playOverlay','hint','zoomValue'].map(id => [id, document.getElementById(id)]));
  const scene = [];
  const presets = {
    block: {name:'Part', size:[4,2,4], color:'#5592c8', kind:'part'},
    spawn: {name:'SpawnLocation', size:[5,0.35,5], color:'#50c88a', kind:'spawn'},
    coin: {name:'Coin', size:[1.6,1.6,0.45], color:'#f2bd43', kind:'coin'},
    tree: {name:'Tree', size:[3,7,3], color:'#55a866', kind:'tree'}
  };
  let selected = null, activeTool = 'select', placing = null, zoom = 1, camera = {x:0,z:0}, placementColor = '#5592c8';
  let playing = false, keys = new Set(), player = {x:0,z:0,y:0,vy:0,grounded:true}, toastTimer = 0, drag = null, search = '';
  let snap = true, grid = 1, time = 0;
  const clamp = (n,a,b) => Math.max(a,Math.min(b,n));
  const esc = s => String(s).replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  function tell(message){ui.outputMessage.textContent=message;ui.statusText.textContent=message;}
  function toast(message){ui.toast.textContent=message;ui.toast.classList.add('show');toastTimer=1.8;}
  function makeObject(type,x=0,z=0){const p=presets[type];return {id:`obj-${Math.random().toString(36).slice(2,8)}`,name:p.name,kind:p.kind,x,y:p.size[1]/2,z,sx:p.size[0],sy:p.size[1],sz:p.size[2],color:p.color,locked:false};}
  function seed(){scene.length=0;const floor=makeObject('block');Object.assign(floor,{id:'baseplate',name:'Baseplate',x:0,y:-.5,z:0,sx:50,sy:1,sz:34,color:'#687b77',locked:true,kind:'floor'});scene.push(floor);const spawn=makeObject('spawn');Object.assign(spawn,{id:'spawn',x:0,y:.18,z:0});scene.push(spawn);selected=spawn;updateUI();tell('Welcome to Block Studio. Your world is ready.');}
  function project(x,y,z){const k=zoom;return {x:W/2+(x-camera.x-z+camera.z)*10.5*k,y:H*.49+(x-camera.x+z-camera.z)*5.4*k-y*17*k};}
  function corners(o){const x=o.x,z=o.z,a=o.sx/2,b=o.sz/2,lo=o.y-o.sy/2,hi=o.y+o.sy/2;return [[x-a,hi,z-b],[x+a,hi,z-b],[x+a,hi,z+b],[x-a,hi,z+b],[x-a,lo,z-b],[x+a,lo,z-b],[x+a,lo,z+b],[x-a,lo,z+b]].map(v=>project(...v));}
  function shade(hex,amount){const n=parseInt(hex.slice(1),16),r=clamp((n>>16)+amount,0,255),g=clamp(((n>>8)&255)+amount,0,255),b=clamp((n&255)+amount,0,255);return `rgb(${r},${g},${b})`;}
  function polygon(points,fill,stroke=null,width=1){ctx.beginPath();ctx.moveTo(points[0].x,points[0].y);for(let i=1;i<points.length;i++)ctx.lineTo(points[i].x,points[i].y);ctx.closePath();ctx.fillStyle=fill;ctx.fill();if(stroke){ctx.strokeStyle=stroke;ctx.lineWidth=width;ctx.stroke();}}
  function drawGrid(){const lines=[];for(let x=-25;x<=25;x+=2){lines.push([project(x,0,-17),project(x,0,17)])}for(let z=-17;z<=17;z+=2)lines.push([project(-25,0,z),project(25,0,z)]);ctx.save();ctx.strokeStyle='#d5dfd833';ctx.lineWidth=1;for(const l of lines){ctx.beginPath();ctx.moveTo(l[0].x,l[0].y);ctx.lineTo(l[1].x,l[1].y);ctx.stroke()}ctx.restore();}
  function drawSky(){const g=ctx.createLinearGradient(0,0,0,H);g.addColorStop(0,'#83b9d8');g.addColorStop(.52,'#b9d5de');g.addColorStop(1,'#d9e2d9');ctx.fillStyle=g;ctx.fillRect(0,0,W,H);ctx.fillStyle='#ffffff25';for(let i=0;i<5;i++){const x=((i*271+time*3)%(W+150))-50;ctx.beginPath();ctx.ellipse(x,105+i%3*28,62,12,0,0,Math.PI*2);ctx.ellipse(x-23,101+i%3*28,22,12,0,0,Math.PI*2);ctx.ellipse(x+25,99+i%3*28,29,16,0,0,Math.PI*2);ctx.fill()}ctx.fillStyle='#8ba99d';ctx.beginPath();ctx.moveTo(0,350);for(let x=0;x<=W;x+=60)ctx.lineTo(x,320+Math.sin(x*.012)*21+Math.sin(x*.031)*9);ctx.lineTo(W,H);ctx.lineTo(0,H);ctx.fill();}
  function drawBox(o){const c=corners(o),col=o.color;ctx.save();if(o.kind==='coin'){const center=project(o.x,o.y,o.z);ctx.fillStyle='#6b531f55';ctx.beginPath();ctx.ellipse(center.x+3,center.y+12,17*zoom,7*zoom,0,0,Math.PI*2);ctx.fill();ctx.fillStyle=col;ctx.strokeStyle='#ffe18a';ctx.lineWidth=2;ctx.beginPath();ctx.ellipse(center.x,center.y,9*zoom,17*zoom,.12,0,Math.PI*2);ctx.fill();ctx.stroke();ctx.fillStyle='#fff0b5';ctx.font=`bold ${12*zoom}px sans-serif`;ctx.textAlign='center';ctx.fillText('$',center.x,center.y+4*zoom);ctx.restore();return;}
    // Visible sides, then the top face, for a clean toy-block silhouette.
    polygon([c[1],c[2],c[6],c[5]],shade(col,-32));polygon([c[2],c[3],c[7],c[6]],shade(col,-18));polygon([c[0],c[1],c[2],c[3]],shade(col,12));
    if(o.kind==='spawn'){const m=project(o.x,o.y+o.sy/2+.03,o.z);ctx.strokeStyle='#e7fff0';ctx.lineWidth=2;ctx.beginPath();ctx.arc(m.x,m.y,10*zoom,0,Math.PI*2);ctx.stroke();ctx.fillStyle='#e7fff0';ctx.font=`bold ${9*zoom}px sans-serif`;ctx.textAlign='center';ctx.fillText('SPAWN',m.x,m.y+25*zoom);}
    if(o.kind==='tree'){const top=project(o.x,o.y+o.sy/2+1.5,o.z);const trunk=project(o.x,o.y+o.sy/2-.2,o.z);ctx.fillStyle='#80603d';ctx.fillRect(trunk.x-5*zoom,trunk.y,10*zoom,28*zoom);ctx.fillStyle='#39804c';for(const [dx,dy,r] of [[0,-3,20],[-13,8,14],[13,7,15]]){ctx.beginPath();ctx.arc(top.x+dx*zoom,top.y+dy*zoom,r*zoom,0,Math.PI*2);ctx.fill();}}
    if(selected===o){polygon([c[0],c[1],c[2],c[3]],'#ffffff12','#f3fbff',2);ctx.setLineDash([5,4]);ctx.strokeStyle='#f3fbffbb';ctx.lineWidth=1;ctx.beginPath();for(const p of [c[0],c[1],c[2],c[3],c[0]]){if(p===c[0])ctx.moveTo(p.x,p.y);else ctx.lineTo(p.x,p.y)}ctx.stroke();ctx.setLineDash([]);}
    ctx.restore();}
  function drawPlayer(){const body=project(player.x,player.y+1.3,player.z),head=project(player.x,player.y+2.55,player.z);ctx.save();ctx.fillStyle='#182a3555';ctx.beginPath();ctx.ellipse(body.x,project(player.x,0,player.z).y+3,12,5,0,0,Math.PI*2);ctx.fill();ctx.fillStyle='#2875c7';ctx.fillRect(body.x-8,body.y-10,16,25);ctx.fillStyle='#e4b892';ctx.fillRect(head.x-7,head.y-7,14,14);ctx.fillStyle='#344a65';ctx.fillRect(body.x-7,body.y+14,6,13);ctx.fillRect(body.x+1,body.y+14,6,13);ctx.fillStyle='#f0f3f5';ctx.fillRect(head.x-5,head.y-1,2,2);ctx.fillRect(head.x+3,head.y-1,2,2);ctx.restore();}
  function render(){drawSky();drawGrid();const ordered=[...scene].sort((a,b)=>(a.x+a.z+a.y*.1)-(b.x+b.z+b.y*.1));for(const o of ordered)drawBox(o);if(playing)drawPlayer();if(selected){const p=project(selected.x,selected.y,selected.z);ui.coords.textContent=`X ${selected.x.toFixed(1)}  Y ${selected.y.toFixed(1)}  Z ${selected.z.toFixed(1)}`;}else ui.coords.textContent=`CAMERA  ${Math.round(zoom*100)}%`;}
  function updateTree(){const rows=scene.filter(o=>!search||o.name.toLowerCase().includes(search)||o.kind.includes(search));ui.tree.innerHTML=`<div class="tree-row" data-world="1"><span class="caret">⌄</span><span class="tree-icon world">◈</span>World</div><div class="tree-children">${rows.map(o=>`<div class="tree-row ${selected===o?'selected':''}" data-id="${o.id}" title="${esc(o.name)}"><span class="caret"></span><span class="tree-icon ${o.kind==='spawn'?'spawn':o.kind==='floor'?'folder':'part'}">${o.kind==='spawn'?'✣':o.kind==='floor'?'▰':o.kind==='coin'?'◉':o.kind==='tree'?'♣':'▧'}</span>${esc(o.name)}</div>`).join('')}</div>`;ui.tree.querySelectorAll('[data-id]').forEach(row=>row.addEventListener('click',()=>select(scene.find(o=>o.id===row.dataset.id))));ui.objectCount.textContent=`${scene.length} objects`;}
  function updateProperties(){if(!selected){ui.propertyContent.innerHTML='<div class="property-empty">Select an object to view its properties.</div>';return;}const o=selected;ui.propertyContent.innerHTML=`<div class="property-title">${esc(o.name)}</div><div class="prop-section">GENERAL</div><label class="prop-row">Name<input data-prop="name" value="${esc(o.name)}"></label><label class="prop-row">Class<select data-prop="kind" ${o.kind==='floor'?'disabled':''}><option value="${o.kind}">${esc(o.kind==='part'?'Part':o.kind)}</option></select></label><div class="prop-section">TRANSFORM</div>${[['X','x'],['Y','y'],['Z','z'],['Width','sx'],['Height','sy'],['Depth','sz']].map(([label,key])=>`<label class="prop-row">${label}<input type="number" step="0.5" data-prop="${key}" value="${Number(o[key]).toFixed(1)}" ${o.locked?'disabled':''}></label>`).join('')}<div class="prop-section">APPEARANCE</div><label class="prop-row">Color<input type="color" data-prop="color" value="${o.color}"></label><label class="prop-row">Anchored<select data-prop="locked"><option value="false" ${!o.locked?'selected':''}>No</option><option value="true" ${o.locked?'selected':''}>Yes</option></select></label>`;
    ui.propertyContent.querySelectorAll('[data-prop]').forEach(input=>input.addEventListener('change',()=>{const key=input.dataset.prop;let value=input.value;if(['x','y','z','sx','sy','sz'].includes(key))value=Number(value);if(key==='locked')value=value==='true';if(key==='name')value=value.trim()||'Part';o[key]=value;if(['sx','sy','sz'].includes(key))o[key]=Math.max(.2,value);if(key==='color'&&o===selected)document.querySelector('.color-button i').style.background=o.color;updateUI();}));}
  function updateUI(){updateTree();updateProperties();canvas.style.cursor=placing?'copy':activeTool==='move'?'move':'crosshair';}
  function select(o){selected=o||null;if(o)document.querySelector('.color-button i').style.background=o.color;updateUI();render();}
  function snapTo(v){return snap?Math.round(v/grid)*grid:v;}
  function viewportPoint(e){const r=canvas.getBoundingClientRect();return {x:(e.clientX-r.left)*W/r.width,y:(e.clientY-r.top)*H/r.height};}
  function unproject(x,y){const k=10.5*zoom,ky=5.4*zoom,a=(x-W/2)/k,b=(y-H*.49)/ky;return {x:camera.x+(a+b)/2,z:camera.z+(b-a)/2};}
  function inside(p,poly){let yes=false;for(let i=0,j=poly.length-1;i<poly.length;j=i++){const a=poly[i],b=poly[j];if(((a.y>p.y)!==(b.y>p.y))&&(p.x<(b.x-a.x)*(p.y-a.y)/(b.y-a.y)+a.x))yes=!yes;}return yes;}
  function hitTest(p){const ordered=[...scene].reverse();for(const o of ordered){const c=corners(o);if(inside(p,[c[0],c[1],c[2],c[3]])||inside(p,[c[1],c[2],c[6],c[5]])||inside(p,[c[2],c[3],c[7],c[6]]))return o;}return null;}
  function add(type,x,z){const o=makeObject(type,snapTo(x),snapTo(z));if(type==='tree')o.y=3.5;scene.push(o);selected=o;placing=null;document.querySelectorAll('.insert-btn').forEach(b=>b.classList.remove('active'));tell(`${o.name} inserted into Workspace.`);toast(`${o.name.toUpperCase()} ADDED`);updateUI();render();}
  canvas.addEventListener('pointerdown',e=>{if(playing)return;const p=viewportPoint(e),ground=unproject(p.x,p.y);if(placing){add(placing,ground.x,ground.z);return;}const o=hitTest(p);if(activeTool==='delete'){if(o&&!o.locked){scene.splice(scene.indexOf(o),1);select(null);tell(`${o.name} deleted.`);}return;}select(o);if(activeTool==='move'&&o&&!o.locked){drag={o,start:ground,ox:o.x,oz:o.z};canvas.setPointerCapture(e.pointerId);}});
  canvas.addEventListener('pointermove',e=>{if(!drag)return;const p=viewportPoint(e),g=unproject(p.x,p.y);drag.o.x=snapTo(drag.ox+g.x-drag.start.x);drag.o.z=snapTo(drag.oz+g.z-drag.start.z);updateTree();updateProperties();render();});
  canvas.addEventListener('pointerup',()=>{if(drag){tell(`${drag.o.name} moved.`);drag=null;}});
  canvas.addEventListener('wheel',e=>{e.preventDefault();zoom=clamp(zoom+(e.deltaY<0?.08:-.08),.55,1.8);ui.zoomValue.textContent=`${Math.round(zoom*100)}%`;render();},{passive:false});
  document.querySelectorAll('.tool').forEach(b=>b.addEventListener('click',()=>{activeTool=b.dataset.tool;placing=null;document.querySelectorAll('.tool').forEach(x=>x.classList.toggle('active',x===b));document.querySelectorAll('.insert-btn').forEach(x=>x.classList.remove('active'));tell(`${activeTool[0].toUpperCase()+activeTool.slice(1)} tool selected.`);updateUI();}));
  document.querySelectorAll('.insert-btn').forEach(b=>b.addEventListener('click',()=>{placing=b.id==='insertBlock'?'block':b.id==='insertSpawn'?'spawn':b.id==='insertCoin'?'coin':'tree';activeTool='select';document.querySelectorAll('.tool').forEach(x=>x.classList.toggle('active',x.dataset.tool==='select'));document.querySelectorAll('.insert-btn').forEach(x=>x.classList.toggle('active',x===b));tell(`Click the world to place a ${presets[placing].name}.`);toast(`CLICK TO PLACE ${presets[placing].name.toUpperCase()}`);updateUI();}));
  const picker=document.createElement('input');picker.type='color';picker.value=placementColor;picker.style.cssText='position:fixed;left:-100px;opacity:0';document.body.appendChild(picker);document.getElementById('colorBtn').addEventListener('click',()=>{picker.value=selected?.color||placementColor;picker.click();});picker.addEventListener('input',()=>{placementColor=picker.value;if(selected){selected.color=picker.value;document.querySelector('.color-button i').style.background=picker.value;updateProperties();}render();});picker.addEventListener('change',()=>{if(selected)tell(`${selected.name} color updated.`);});
  document.getElementById('snapToggle').addEventListener('change',e=>snap=e.target.checked);document.getElementById('gridSize').addEventListener('change',e=>grid=Number(e.target.value));
  document.getElementById('searchInput').addEventListener('input',e=>{search=e.target.value.toLowerCase();updateTree();});
  document.getElementById('resetBtn').addEventListener('click',()=>{seed();toast('WORLD RESET');});
  document.getElementById('zoomIn').addEventListener('click',()=>{zoom=clamp(zoom+.1,.55,1.8);ui.zoomValue.textContent=`${Math.round(zoom*100)}%`;render();});document.getElementById('zoomOut').addEventListener('click',()=>{zoom=clamp(zoom-.1,.55,1.8);ui.zoomValue.textContent=`${Math.round(zoom*100)}%`;render();});document.getElementById('cameraBtn').addEventListener('click',()=>{zoom=1;camera={x:0,z:0};ui.zoomValue.textContent='100%';render();});
  document.getElementById('fullscreenBtn').addEventListener('click',()=>{document.querySelector('.workspace').classList.toggle('focus-mode');});
  document.getElementById('playBtn').addEventListener('click',startPlay);document.getElementById('stopBtn').addEventListener('click',stopPlay);
  function startPlay(){playing=true;placing=null;player={x:0,z:0,y:0,vy:0,grounded:true};ui.playOverlay.classList.remove('hidden');ui.hint.classList.add('hidden');tell('Play test started. Use WASD to explore; press ESC to return.');canvas.focus();render();}
  function stopPlay(){playing=false;keys.clear();ui.playOverlay.classList.add('hidden');ui.hint.classList.remove('hidden');tell('Play test stopped. Back to editing.');render();}
  document.getElementById('helpBtn').addEventListener('click',()=>document.getElementById('helpModal').classList.remove('hidden'));document.getElementById('closeHelp').addEventListener('click',()=>document.getElementById('helpModal').classList.add('hidden'));document.getElementById('helpOkay').addEventListener('click',()=>document.getElementById('helpModal').classList.add('hidden'));
  document.getElementById('clearOutput').addEventListener('click',()=>tell('Output cleared.'));document.getElementById('outputToggle').addEventListener('click',()=>document.querySelector('.output').classList.toggle('collapsed'));
  document.querySelectorAll('.rail').forEach(b=>b.addEventListener('click',()=>{document.querySelectorAll('.rail').forEach(x=>x.classList.toggle('active',x===b));toast(`${b.title.toUpperCase()} PANEL`);}));
  window.addEventListener('keydown',e=>{if(e.repeat)return;const tag=document.activeElement?.tagName;if(tag==='INPUT'||tag==='SELECT'||tag==='TEXTAREA')return;if(playing){if(e.key==='Escape'){stopPlay();return;}if(['w','a','s','d','W','A','S','D',' '].includes(e.key)){e.preventDefault();keys.add(e.key.toLowerCase());}return;}if(e.key==='Delete'||e.key==='Backspace'){if(selected&&!selected.locked){const name=selected.name;scene.splice(scene.indexOf(selected),1);select(null);tell(`${name} deleted.`);}}if(e.key==='Escape'){placing=null;updateUI();}});
  window.addEventListener('keyup',e=>keys.delete(e.key.toLowerCase()));window.addEventListener('blur',()=>keys.clear());
  function tick(dt){time+=dt;if(playing){const speed=8*dt;let dx=0,dz=0;if(keys.has('w'))dz-=speed;if(keys.has('s'))dz+=speed;if(keys.has('a'))dx-=speed;if(keys.has('d'))dx+=speed;if(dx&&dz){dx*=.707;dz*=.707;}player.x=clamp(player.x+dx,-23,23);player.z=clamp(player.z+dz,-15,15);if(keys.has(' ')&&player.grounded){player.vy=9;player.grounded=false;}player.y+=player.vy*dt;player.vy-=24*dt;if(player.y<=0){player.y=0;player.vy=0;player.grounded=true;}}if(toastTimer>0){toastTimer-=dt;if(toastTimer<=0)ui.toast.classList.remove('show');}}
  let last=performance.now();function frame(now){const dt=Math.min(.05,(now-last)/1000);last=now;tick(dt);render();requestAnimationFrame(frame);}
  seed();requestAnimationFrame(frame);
})();

