Index: game.js
===================================================================
--- game.js
+++ game.js
@@ -55,8 +55,9 @@
   const picker=document.createElement('input');picker.type='color';picker.value=placementColor;picker.style.cssText='position:fixed;left:-100px;opacity:0';document.body.appendChild(picker);document.getElementById('colorBtn').addEventListener('click',()=>{picker.value=selected?.color||placementColor;picker.click();});picker.addEventListener('input',()=>{placementColor=picker.value;if(selected){selected.color=picker.value;document.querySelector('.color-button i').style.background=picker.value;updateProperties();}render();});picker.addEventListener('change',()=>{if(selected)tell(`${selected.name} color updated.`);});
   document.getElementById('snapToggle').addEventListener('change',e=>snap=e.target.checked);document.getElementById('gridSize').addEventListener('change',e=>grid=Number(e.target.value));
   document.getElementById('searchInput').addEventListener('input',e=>{search=e.target.value.toLowerCase();updateTree();});
   document.getElementById('resetBtn').addEventListener('click',()=>{seed();toast('WORLD RESET');});
+  document.getElementById('saveBtn').addEventListener('click',()=>{const data={format:'Block Studio Place',version:1,objects:scene.map(({id,...o})=>o)};const link=document.createElement('a');link.href=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'}));link.download='untitled-place.json';link.click();URL.revokeObjectURL(link.href);document.querySelector('.file-name').innerHTML='Untitled Place <i>•</i> Saved';tell('Place saved as untitled-place.json.');toast('PLACE SAVED');});
   document.getElementById('zoomIn').addEventListener('click',()=>{zoom=clamp(zoom+.1,.55,1.8);ui.zoomValue.textContent=`${Math.round(zoom*100)}%`;render();});document.getElementById('zoomOut').addEventListener('click',()=>{zoom=clamp(zoom-.1,.55,1.8);ui.zoomValue.textContent=`${Math.round(zoom*100)}%`;render();});document.getElementById('cameraBtn').addEventListener('click',()=>{zoom=1;camera={x:0,z:0};ui.zoomValue.textContent='100%';render();});
   document.getElementById('fullscreenBtn').addEventListener('click',()=>{document.querySelector('.workspace').classList.toggle('focus-mode');});
   document.getElementById('playBtn').addEventListener('click',startPlay);document.getElementById('stopBtn').addEventListener('click',stopPlay);
   function startPlay(){playing=true;placing=null;player={x:0,z:0,y:0,vy:0,grounded:true};ui.playOverlay.classList.remove('hidden');ui.hint.classList.add('hidden');tell('Play test started. Use WASD to explore; press ESC to return.');canvas.focus();render();}

